/**
 * Runtime layer for the calculated-field DSL — coercion + node
 * construction.
 *
 * Every `calc.*` builder funnels its inputs through `coerce()`, which
 * normalizes one of {already-an-Expr, typed AppField, raw literal}
 * into an `Expr<T>`. The builder then composes the resulting
 * `toCalcString()` closures into a parent node. No mutable AST — each
 * node carries its own serializer closure built at construction time.
 *
 * Wire-format choices baked in here:
 *   - Field refs emit `"<uuid>"` when the field has a UUID id, and
 *     `"<name>"` otherwise. Both forms parse on the server. The UUID
 *     form is preferred because it's rename-safe; the name form is
 *     the fallback for placeholder-id fields being created in the
 *     same compose (the server resolves the name within the request).
 *   - String literals are single-quoted with `''` escapes per the
 *     ANTLR grammar.
 *   - Boolean literals are `TRUE()` / `FALSE()` (the parser accepts
 *     both these and the bare keywords; the function form is the
 *     canonical shape per the Java test).
 */
import { isRef } from "../../shared/ref.js";
import { isUuid } from "../../../../pull/util.js";
// ---------------------------------------------------------------------------
// Node construction
// ---------------------------------------------------------------------------
/**
 * Build an `Expr<T>` node from its type brand and a serializer
 * closure. Internal — public builders compose this.
 */
export function makeExpr(type, serialize, metadata) {
    return {
        __calc: true,
        __exprType: type,
        __exprCardinality: metadata?.cardinality ?? "single",
        __exprContext: metadata?.context ?? "standalone",
        toCalcString: serialize,
    };
}
/**
 * True if `value` is already an `Expr<T>` (built by a prior `calc.*`
 * call or a pulled-expression marker). Discriminator-checked.
 */
export function isExpr(value) {
    return (typeof value === "object" &&
        value !== null &&
        "__calc" in value &&
        value.__calc === true);
}
/** Aggregate runtime context metadata for a composed expression. */
export function expressionContext(expressions) {
    return expressions.some((expression) => expression.__exprContext === "record") ? "record" : "standalone";
}
/** Build a scalar parent node while preserving record-context metadata. */
export function makeComposedExpr(type, expressions, serialize) {
    return makeExpr(type, serialize, { context: expressionContext(expressions) });
}
/**
 * Build a comparison node, tagged so {@link assertCalculatedFieldRoot} can
 * reject it at the root of a calculation. The grammar's root production is
 * "expression", which covers arithmetic, function calls, column refs and
 * literals but NOT comparisons — those are a separate "boolean expression"
 * production reachable only as a function argument.
 */
export function makeComparisonExpr(expressions, serialize) {
    return {
        ...makeComposedExpr("bool", expressions, serialize),
        __exprBoolShape: "comparison",
    };
}
/**
 * Throw when `expression` is a comparison standing alone as a whole
 * calculated field. `owner` names the field in the message so the author can
 * find it without reading the generated HCL.
 *
 * Scoped to calculated fields: the provider runs
 * `aspectFieldCalculationValidateV3` on every create and update there, so the
 * shape is a hard apply failure. Automation calculation tasks validate only on
 * read, where the provider degrades to a diagnostic.
 */
export function assertCalculatedFieldRoot(expression, owner) {
    if (expression.__exprBoolShape !== "comparison")
        return;
    const subject = owner === undefined ? "calculation" : `calculation "${owner}"`;
    throw new Error(`${subject}: a comparison cannot be the whole calculation — the platform ` +
        `parses "${expression.toCalcString()}" as a boolean expression, which its ` +
        `grammar only accepts inside a function. Wrap it, e.g. ` +
        `calc.if(<comparison>, true, false).`);
}
/**
 * True if `value` looks like an `AppField`. Structural check — looks
 * for the `type` + `id` + `name` triplet every variant carries.
 */
function isAppField(value) {
    return (typeof value === "object" &&
        value !== null &&
        "type" in value &&
        "id" in value &&
        "name" in value);
}
function isFieldRef(value) {
    return (typeof value === "object" &&
        value !== null &&
        "__kind" in value &&
        value.__kind === "field" &&
        "fieldType" in value &&
        "name" in value);
}
// ---------------------------------------------------------------------------
// Field-ref serialization
// ---------------------------------------------------------------------------
/**
 * Emit the wire form of a field reference. UUID ids emit as
 * `"<uuid>"`; placeholder ids fall back to `"<name>"`. The server
 * accepts both inside the same compose body.
 *
 * Field name quoting uses `""` escapes (ANSI SQL double-quote
 * doubling) per the ANTLR grammar's IDENTIFIER_QUOTED rule.
 */
export function emitFieldRef(field) {
    if (isUuid(field.id)) {
        return `"${field.id}"`;
    }
    return `"${field.name.replace(/"/g, '""')}"`;
}
/**
 * Map an `AppField.type` to the matching `ExprType` brand. Used by
 * `coerce()` when wrapping a bare field handle into an `Expr<T>`.
 *
 * `CALCULATED` deliberately throws — a calculated field's output type
 * is server-inferred and the EDK doesn't know it locally without
 * walking the source expression. Allowing cross-calculated refs would
 * need an inference pass; deferred from v1.
 */
function appFieldExprType(field) {
    switch (field.type) {
        case "NUMBER": return "number";
        case "DECIMAL": return "decimal";
        case "TEXT":
        case "RICH_TEXT": return "text";
        case "HTML": return "html";
        case "HANDLE": return "handle";
        case "BOOLEAN": return "bool";
        case "DATE": return "date";
        case "DATETIME": return "datetime";
        case "PICKLIST": return "picklist";
        case "MULTI_PICKLIST": return "multiPicklist";
        case "USER":
        case "USER_ID": return "user";
        case "GROUP":
        case "GROUP_ID": return "group";
        case "ATTACHMENT":
        case "ATTACHMENT_ID": return "attachment";
        case "JSON": return "json";
        case "CALCULATED":
            throw new Error(`calc: cannot reference calculated field "${field.name}" inside another ` +
                `calculation — referring to a calculated field's value needs the server ` +
                `to infer its output type, which the EDK doesn't replicate locally. ` +
                `Inline the upstream expression or split the work across automation tasks.`);
        case "RELATION":
            throw new Error(`calc: cannot reference relation field "${field.name}" in a calculation — ` +
                `it has no scalar/comparable value of its own (relatedObject/relatedLabelField ` +
                `are a catalog token or raw platform id, not an expression-typed value).`);
        default: {
            const _exhaustive = field;
            void _exhaustive;
            throw new Error(`calc: unsupported field type on "${field.name}"`);
        }
    }
}
function catalogFieldExprType(field) {
    switch (field.fieldType) {
        case "NUMBER": return "number";
        case "DECIMAL": return "decimal";
        case "TEXT":
        case "RICH_TEXT": return "text";
        case "HANDLE": return "handle";
        case "HTML": return "html";
        case "BOOLEAN": return "bool";
        case "DATE": return "date";
        case "DATETIME": return "datetime";
        case "PICKLIST": return "picklist";
        case "MULTI_PICKLIST": return "multiPicklist";
        case "USER":
        case "USER_ID": return "user";
        case "GROUP":
        case "GROUP_ID": return "group";
        case "ATTACHMENT":
        case "ATTACHMENT_ID": return "attachment";
        case "JSON": return "json";
        default:
            throw new Error(`calc: unsupported catalog field type "${field.fieldType}" on "${field.name}".`);
    }
}
let activeWorkflowRefRenderer;
/** Install the automation calculation parameter collector for one render. */
export function withWorkflowRefRenderer(renderer, render) {
    if (activeWorkflowRefRenderer !== undefined) {
        throw new Error("nested calculation expression rendering is not supported.");
    }
    activeWorkflowRefRenderer = renderer;
    try {
        return render();
    }
    finally {
        activeWorkflowRefRenderer = undefined;
    }
}
// ---------------------------------------------------------------------------
// Literal serialization
// ---------------------------------------------------------------------------
/**
 * Quote a TS string for the wire. Single-quoted with `''` escapes per
 * the ANTLR grammar's STRING_LITERAL rule.
 */
export function emitStringLiteral(value) {
    return `'${value.replace(/'/g, "''")}'`;
}
// ---------------------------------------------------------------------------
// Coercion
// ---------------------------------------------------------------------------
/**
 * Normalize an `ExprLike<T>` into an `Expr<T>`. The three branches:
 *
 *   1. Already an `Expr<T>` (or a pulled-expression marker) → return
 *      verbatim.
 *   2. An `AppField` handle → wrap as an `Expr<...>` whose
 *      `toCalcString()` emits the wire field reference.
 *   3. A raw TS literal (number / string / boolean) → wrap as a
 *      typed literal expression.
 *
 * The function's input type is `ExprLike<T>` so TypeScript already
 * narrowed which `T` is expected at the call site; the runtime
 * branches just route the value through the right factory. Coercion
 * doesn't validate that the value's actual type matches `T` — the
 * compile-time `ExprLike<T>` union prevents the mismatch from ever
 * reaching here.
 */
export function coerce(value) {
    if (isExpr(value)) {
        return value;
    }
    if (isFieldRef(value)) {
        const field = value;
        const exprType = catalogFieldExprType(field);
        return makeExpr(exprType, () => `"${field.name.replace(/"/g, '""')}"`, { context: "record" });
    }
    if (isAppField(value)) {
        const field = value;
        const exprType = appFieldExprType(field);
        return makeExpr(exprType, () => emitFieldRef(field), { context: "record" });
    }
    if (isRef(value)) {
        const ref = value;
        return makeExpr("text", () => {
            if (activeWorkflowRefRenderer === undefined) {
                throw new Error("workflow refs can only be rendered by calculation(); pass this expression directly to a calculation value.");
            }
            return activeWorkflowRefRenderer(ref);
        });
    }
    if (typeof value === "number") {
        // Integer → number, fractional → decimal. The runtime split
        // matches the server's promotion: any non-integer literal forces
        // decimal context.
        const branded = Number.isInteger(value) ? "number" : "decimal";
        return makeExpr(branded, () => String(value));
    }
    if (typeof value === "string") {
        return makeExpr("text", () => emitStringLiteral(value));
    }
    if (typeof value === "boolean") {
        return makeExpr("bool", () => (value ? "TRUE()" : "FALSE()"));
    }
    throw new Error(`calc: cannot coerce value of type "${typeof value}" to Expr — pass a calc.* node, an AppField handle, or a primitive literal.`);
}
